class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self.options = set()
        self.votes = {}  # option -> vote count
        self.voters = {}  # voter -> option they voted for

    def add_option(self, option: str) -> None:
        self.options.add(option)
        if option not in self.votes:
            self.votes[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if option not in self.options:
            raise ValueError(f"Option '{option}' does not exist")
        if voter in self.voters:
            raise ValueError(f"Voter '{voter}' has already voted")

        self.voters[voter] = option
        self.votes[option] += 1

    def winner(self) -> str | None:
        if len(self.voters) < 3:
            return None

        # Find the option with the maximum votes
        max_votes = -1
        winner_option = None
        for option, vote_count in self.votes.items():
            if vote_count > max_votes:
                max_votes = vote_count
                winner_option = option

        return winner_option
